document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("jobs-list");if(!n)return;const o=ForjaStorage.getVagas().filter(n=>"Aberta"===n.status);0!==o.length?(o.forEach(o=>{n.innerHTML+=`\n\n\n<div class="job-card">\n\n\n\n<h3>\n${o.titulo}\n</h3>\n\n\n\n<p>\n${o.descricao}\n</p>\n\n\n\n<p>\n<strong>\nSetor:\n</strong>\n${o.setor}\n</p>\n\n\n\n<p>\n<strong>\nLocal:\n</strong>\n${o.local}\n</p>\n\n\n\n\n<button \nonclick="selecionarVaga('${o.titulo}')">\n\nCandidatar-se\n\n</button>\n\n\n\n</div>\n\n\n`}),window.selecionarVaga=n=>{const o=document.getElementById("cargo");o&&(o.value=n,window.scrollTo({top:o.offsetTop-100,behavior:"smooth"}))}):n.innerHTML="\n\n<p>\nNo momento não temos vagas abertas.\n</p>\n\n"});